      const l = luma(r, g, b);
      const [sr, sg, sb] = sat(r + 0.06 * l, g - 0.03, b + 0.08 * (1 - l) + 0.03, 1.3);
      return [contrast(sr, 1.1), contrast(sg, 1.1), contrast(sb, 1.1)];
